def begin(out_dir: str, cache_dir: str, schema_version: str, progress) -> "Session":
    """Открыть сессию расчёта. Вызывается один раз на запуск."""

class Session:
    def add_file(self, name: str, mtime_ms: int, size: int, path: str) -> str:
        """Файл пользователя уже лежит по `path`. Вернуть ровно одно из:
        "parsed"  — файл разобран сейчас (агрегаты обновлены);
        "cached"  — файл узнан по кэшу, разбор пропущен;
        "service" — служебный файл (справочник, override): движок сохранит
                    его на диске до конца finish(); остальные удаляются
                    НЕМЕДЛЕННО после возврата — путь хранить нельзя."""

    def finish(self) -> dict:
        """Дописать выходы в out_dir и вернуть их имена (относительно out_dir):
        {"html": "dashboard.html" | None,
         "slots": {"0": "sales_data.bin.gz", ...},
         "write_back": {"1": "sales_review.xlsx"} | {}}"""

import pandas as pd

def begin(out_dir, cache_dir, schema_version, progress):
    return Session(out_dir, progress)

class Session:
    def __init__(self, out_dir, progress):
        self.out_dir = out_dir
        self.progress = progress
        self.totals = {}
        self.ref_path = None

    def add_file(self, name, mtime_ms, size, path):
        if name.lower() == "regions.xlsx":        # справочник регионов
            self.ref_path = path                  # прочитаем позже, в finish()
            return "parsed"
        df = pd.read_excel(path, sheet_name="Данные")
        for i, row in enumerate(df.itertuples()):
            self.progress("rows", i, len(df), name)
            key = row.region
            self.totals[key] = self.totals.get(key, 0) + row.qty
        return "parsed"

