{
  "name": "sales-weekly",
  "version": "1.4.0",
  "entrypoint": { "module": "sales_weekly.engine" },
  "deps": [
    { "name": "pandas",          "version": "3.0.3" },
    { "name": "python-calamine", "version": "0.8.2" }
  ],
  "inputs": [
    { "match": "Sales_2026_w*.xlsx", "role": "data", "required": true,
      "sheets": [ { "name": "Данные", "columns": ["Код клиента", "Регион", "Кол-во"] } ] },
    { "match": "Regions.xlsx", "role": "reference" }
  ],
  "outputs": {
    "html": true,
    "slots": [
      { "index": 0, "name": "sales_data.bin.gz", "type": "data" },
      { "index": 1, "name": "sales_review.xlsx", "type": "xlsx", "write_back": true }
    ]
  },
  "required_files": ["Regions.xlsx"],
  "aux_inputs": [
    { "name": "sales_review_filled.xlsx", "label": "Запустить с разметкой",
      "download_from": "sales_review.xlsx" }
  ],
  "data_scale": { "max_files": 120, "max_total_bytes": 314572800,
                  "max_file_bytes": 20971520 },
  "engine": "auto",
  "write_back": true
}

{
  "schema_version": 1,
  "tables": {
    "orders": {
      "sources": [{"file": "Sales_2026_w*.xlsx", "sheet": "data", "header_row": 1}],
      "columns": {
        "region":      {"type": "text",   "role": "dim",     "source": "Регион"},
        "client_code": {"type": "text",   "role": "dim",     "source": "Код клиента"},
        "week":        {"type": "number", "role": "time",    "source": "Неделя"},
        "ordered":     {"type": "number", "role": "measure", "source": "Заказано"},
        "shipped":     {"type": "number", "role": "measure", "source": "Отгружено"}
      }
    }
  },
  "kpis": {
    "fill_rate": {
      "name": "Доля выполнения заказа",
      "short": "Выполнение",
      "unit": null,
      "measure": "ratio",
      "question_forms": ["какая доля выполнения заказа", "сколько выполнено от заказа"],
      "cell_sql": "SELECT region, client_code, week, SUM(LEAST(shipped, ordered)) AS n, SUM(ordered) AS d FROM orders GROUP BY 1, 2, 3"
    }
  }
}

